from __future__ import annotations

import asyncio
import typing

import pytest

import llm_router
import tests.llm_router.support.builders as builders

pytestmark = pytest.mark.verification_kind("unit")


def _build_test_router() -> typing.Any:
    """Construct a test router using available builders or LLMRouter facade."""
    if hasattr(builders, "build_router"):
        try:
            return builders.build_router()
        except TypeError:
            pass
        if hasattr(builders, "build_route"):
            try:
                route = builders.build_route()
                return builders.build_router(routes=[route])
            except Exception:
                pass
            try:
                route = builders.build_route()
                return builders.build_router(spec=[route])
            except Exception:
                pass
    if hasattr(builders, "RouterBuilder"):
        try:
            builder = builders.RouterBuilder()
            if hasattr(builder, "build"):
                return builder.build()
        except Exception:
            pass
    if hasattr(builders, "build_runtime"):
        try:
            return builders.build_runtime()
        except Exception:
            pass
    if hasattr(llm_router, "LLMRouter"):
        for candidate in ("test-provider/test-model", "mock/mock-model", "test"):
            try:
                return llm_router.LLMRouter(candidate)
            except Exception:
                pass
    msg = "Unable to construct router from available builders or LLMRouter"
    raise RuntimeError(msg)


@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
def test_async_success_records_success_and_clears_failure_state() -> None:
    """A successful async request must record success and clear prior failure state."""
    router_async = _build_test_router()
    runtime_async = getattr(
        router_async, "_runtime", getattr(router_async, "_impl", router_async)
    )

    record_success_calls: list[tuple[tuple[typing.Any, ...], dict[str, typing.Any]]] = []
    orig_record_success = runtime_async._record_success

    def spy_record_success(*args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        record_success_calls.append((args, kwargs))
        return orig_record_success(*args, **kwargs)

    runtime_async._record_success = spy_record_success

    orig_call_async = runtime_async._call_async_with_timeout
    async_calls = 0

    async def flaky_call_async(request: typing.Any, **kwargs: typing.Any) -> typing.Any:
        nonlocal async_calls
        async_calls += 1
        if async_calls == 1:
            msg = "Simulated transient route failure"
            raise RuntimeError(msg)
        return await orig_call_async(request, **kwargs)

    runtime_async._call_async_with_timeout = flaky_call_async

    # First request: fails on route attempt, recording failure streak in limiter
    try:
        asyncio.run(router_async.aquery("Explain quantum computing"))
    except Exception:
        pass

    assert async_calls == 1, "First async request should have attempted and failed"
    assert len(record_success_calls) == 0, (
        "No success should be recorded after a failed attempt"
    )

    # Second request: succeeds on the route
    response = asyncio.run(router_async.aquery("Explain quantum computing"))
    assert response is not None

    # Crucial assertion: _record_success must be invoked on successful async routing
    assert len(record_success_calls) == 1, (
        "Expected _record_success to be invoked after a successful async request"
    )

    # Verify limiter failure streaks / cooldowns are cleared
    limiter = runtime_async._limiter
    for attr_name in ("failure_streaks", "streaks", "consecutive_failures", "failures"):
        if hasattr(limiter, attr_name):
            val = getattr(limiter, attr_name)
            if isinstance(val, dict):
                assert all(v == 0 for v in val.values()), (
                    f"Expected {attr_name} to be cleared/zeroed after successful async call, got {val}"
                )

    # Compare with sync execution: verify async recovery matches sync recovery routing state
    router_sync = _build_test_router()
    runtime_sync = getattr(
        router_sync, "_runtime", getattr(router_sync, "_impl", router_sync)
    )

    sync_method_name = None
    for candidate in (
        "_call_sync_with_timeout",
        "_call_with_timeout",
        "_call_sync",
        "_execute_sync",
    ):
        if hasattr(runtime_sync, candidate):
            sync_method_name = candidate
            break

    if sync_method_name is not None:
        sync_calls = 0
        orig_sync_call = getattr(runtime_sync, sync_method_name)

        def flaky_call_sync(request: typing.Any, **kwargs: typing.Any) -> typing.Any:
            nonlocal sync_calls
            sync_calls += 1
            if sync_calls == 1:
                msg = "Simulated transient route failure"
                raise RuntimeError(msg)
            return orig_sync_call(request, **kwargs)

        setattr(runtime_sync, sync_method_name, flaky_call_sync)

        try:
            router_sync.query("Explain quantum computing")
        except Exception:
            pass

        router_sync.query("Explain quantum computing")

        # The limiter states between async and sync recovery must match
        for attr in dir(runtime_async._limiter):
            if not attr.startswith("_"):
                async_val = getattr(runtime_async._limiter, attr)
                sync_val = getattr(runtime_sync._limiter, attr)
                if not callable(async_val):
                    assert async_val == sync_val, (
                        f"Routing limiter state mismatch between async and sync for '{attr}': "
                        f"async={async_val!r}, sync={sync_val!r}"
                    )
